356:       function createArena() {
357:         const grid = new THREE.Group();
358:         const floor = new THREE.Mesh(
359:           new THREE.CylinderGeometry(13, 13, 1.3, 64),
360:           new THREE.MeshStandardMaterial({ color: 0x111d2d, emissive: 0x081924, metalness: 0.15, roughness: 0.9 })
361:         );
362:         floor.position.y = -1.75;
363:         floor.receiveShadow = true;
