366:         const ring = new THREE.Mesh(
367:           new THREE.TorusGeometry(10.5, 0.28, 12, 96),
368:           new THREE.MeshStandardMaterial({ color: 0x7d9dff, emissive: 0x1d2d50, roughness: 0.35, metalness: 0.7 })
369:         );
370:         ring.rotation.x = Math.PI / 2;
371:         ring.position.y = -0.95;
372:         grid.add(ring);
