389:       function createPlayer() {
390:         const group = new THREE.Group();
391: 
392:         const body = new THREE.Mesh(
393:           new THREE.CapsuleGeometry(0.6, 1.3, 6, 16),
394:           new THREE.MeshStandardMaterial({ color: 0x6fe0ff, emissive: 0x123546, roughness: 0.35, metalness: 0.46 })
395:         );
396:         body.castShadow = true;
397:         group.add(body);
398: 
399:         const visor = new THREE.Mesh(
400:           new THREE.BoxGeometry(0.8, 0.28, 0.3),
401:           new THREE.MeshStandardMaterial({ color: 0xdff6ff, emissive: 0x5a8eb8, roughness: 0.3 })
402:         );
403:         visor.position.set(0, 0.55, 0.36);
404:         group.add(visor);
