411:       function rand(min, max) {
412:         return Math.random() * (max - min) + min;
413:       }
414: 
415:       function createEnemy(level) {
416:         const root = new THREE.Group();
417:         const hue = 0.005 + (level * 0.005);
418:         const body = new THREE.Mesh(
419:           new THREE.SphereGeometry(0.8, 20, 20),
420:           new THREE.MeshStandardMaterial({ color: new THREE.Color().setHSL(hue, 0.78, 0.52), emissive: 0x5a0b12, roughness: 0.3, metalness: 0.2 })
421:         );
422:         body.scale.set(1, 1.2, 1);
423:         body.castShadow = true;
424:         root.add(body);
425: 
426:         const eye = new THREE.Mesh(
427:           new THREE.BoxGeometry(0.4, 0.16, 0.16),
428:           new THREE.MeshStandardMaterial({ color: 0xfff6f0, emissive: 0xffa08b, roughness: 0.5 })
429:         );
430:         eye.position.set(0, 0.15, 0.7);
431:         root.add(eye);
432: 
433:         const angle = Math.random() * Math.PI * 2;
434:         const r = rand(4.5, 9.5);
435:         root.position.set(Math.cos(angle) * r, 1.3, Math.sin(angle) * r);
436:         root.userData = {
437:           speed: rand(1.1, 1.8 + level * 0.3),
438:           radius: r,
439:           angle,
440:           health: 1 + level * 0.16,
441:           pulse: Math.random() * Math.PI * 2,
442:         };
443: 
444:         scene.add(root);
445:         return root;
446:       }
447: 
448:       function createPickup(x, z) {
449:         const mesh = new THREE.Mesh(
450:           new THREE.OctahedronGeometry(0.45, 0),
451:           new THREE.MeshStandardMaterial({ color: 0x7ef7b7, emissive: 0x143324, roughness: 0.35, metalness: 0.7 })
452:         );
453:         mesh.castShadow = true;
454:         mesh.position.set(x, 0.9, z);
455:         mesh.userData = { bob: Math.random() * Math.PI * 2 };
456:         scene.add(mesh);
457:         return mesh;
458:       }
459: 
460:       function spawnWave() {
461:         const count = 3 + world.level;
462:         for (let i = 0; i < count; i++) {
463:           world.enemies.push(createEnemy(world.level));
464:         }
465:         const pickupCount = 3 + world.level;
466:         for (let i = 0; i < pickupCount; i++) {
467:           const angle = Math.random() * Math.PI * 2;
468:           const r = rand(1.5, 8.5);
469:           world.pickups.push(createPickup(Math.cos(angle) * r, Math.sin(angle) * r));
470:         }
471:       }
472: 
473:       function resetGame() {
474:         world.health = 100;
475:         world.score = 0;
476:         world.combo = 1;
477:         world.level = 1;
478:         world.time = 0;
479:         world.ended = false;
480:         world.started = true;
481:         ui.level.textContent = `Sector 0${world.level}`;
482:         world.player.position.set(0, 0.3, 0);
483:         for (const enemy of world.enemies) scene.remove(enemy);
484:         for (const pickup of world.pickups) scene.remove(pickup);
485:         world.enemies = [];
486:         world.pickups = [];
487:         spawnWave();
488:         updateHUD();
489:       }
490: 
491:       function updateHUD() {
492:         ui.health.textContent = Math.max(0, Math.ceil(world.health));
493:         ui.score.textContent = world.score;
494:         ui.combo.textContent = `x${world.combo}`;
495:         ui.level.textContent = `Sector 0${Math.min(world.level, 5)}`;
496:       }
497: 
498:       function nextLevel() {
499:         if (world.level >= 5) {
500:           world.ended = true;
501:           setOverlay('Victory', 'You survived the gore storm and cleaned the last sector.', 'Play Again', 'good');
502:           world.started = false;
503:           return;
504:         }
505:         world.level += 1;
506:         world.score += 100 * world.combo;
507:         for (const enemy of world.enemies) scene.remove(enemy);
508:         for (const pickup of world.pickups) scene.remove(pickup);
509:         world.enemies = [];
510:         world.pickups = [];
511:         spawnWave();
512:         updateHUD();
513:       }
514: 
515:       function hitPlayer(amount) {
516:         if (world.ended) return;
517:         world.health = Math.max(0, world.health - amount);
518:         world.attacked = true;
519:         if (world.health <= 0) {
520:           world.ended = true;
521:           world.started = false;
522:           setOverlay('Run Failed', 'The plague overwhelmed you. Reboot and try another run.', 'Restart Run', 'accent');
523:           return;
524:         }
525:         updateHUD();
526:       }
527: 
528:       function attackEnemies() {
529:         const playerPos = world.player.position;
530:         let cleared = 0;
531:         for (let i = world.enemies.length - 1; i >= 0; i--) {
532:           const enemy = world.enemies[i];
533:           const dist = enemy.position.distanceTo(playerPos);
534:           if (dist < 1.55) {
535:             enemy.userData.health -= 1.2;
536:             if (enemy.userData.health <= 0) {
537:               scene.remove(enemy);
538:               world.enemies.splice(i, 1);
539:               world.score += 12 * world.combo;
540:               world.combo = Math.min(8, world.combo + 0.25);
541:               cleared += 1;
542:             }
543:           }
544:         }
545: 
546:         if (cleared > 0) {
547:           world.score += cleared * 12;
548:           if (world.enemies.length === 0) {
549:             nextLevel();
550:           }
551:         }
552:       }
553: 
554:       function handleCollectibles() {
555:         const playerPos = world.player.position;
556:         for (let i = world.pickups.length - 1; i >= 0; i--) {
557:           const pickup = world.pickups[i];
558:           if (pickup.position.distanceTo(playerPos) < 1.3) {
559:             scene.remove(pickup);
560:             world.pickups.splice(i, 1);
561:             world.score += 25;
562:             world.health = Math.min(100, world.health + 9);
563:             world.combo = Math.min(8, world.combo + 0.2);
564:           }
565:         }
566:         updateHUD();
567:       }
