569:       function updatePlayer(dt) {
570:         const move = new THREE.Vector3();
571:         if (keys['KeyW']) move.z -= 1;
572:         if (keys['KeyS']) move.z += 1;
573:         if (keys['KeyA']) move.x -= 1;
574:         if (keys['KeyD']) move.x += 1;
575: 
576:         if (move.lengthSq() > 0) {
577:           move.normalize();
578:           const speed = 5.5;
579:           world.player.position.addScaledVector(move, speed * dt);
580:           world.player.position.x = THREE.MathUtils.clamp(world.player.position.x, -9.8, 9.8);
581:           world.player.position.z = THREE.MathUtils.clamp(world.player.position.z, -9.8, 9.8);
582:           const angle = Math.atan2(move.x, move.z);
583:           world.player.rotation.y = angle;
584:         }
585: 
586:         if (keys['Space'] && world.player.position.y < 0.35) {
587:           world.player.position.y = 1.2;
588:           world.player.userData.vy = 8.2;
589:         }
590: 
591:         if (world.player.userData.vy) {
592:           world.player.position.y += world.player.userData.vy * dt;
593:           world.player.userData.vy -= 15 * dt;
594:           if (world.player.position.y < 0.3) {
595:             world.player.position.y = 0.3;
596:             world.player.userData.vy = 0;
597:           }
598:         }
599:       }
600: 
601:       function updateEnemies(dt) {
602:         const playerPos = world.player.position;
603:         for (const enemy of world.enemies) {
604:           const data = enemy.userData;
605:           data.angle += (0.75 + world.level * 0.08) * dt;
606:           const x = Math.cos(data.angle) * data.radius;
607:           const z = Math.sin(data.angle) * data.radius;
608:           enemy.position.x = x;
609:           enemy.position.z = z;
610:           enemy.position.y = 1.2 + Math.sin(world.time * 3 + data.pulse) * 0.18;
