function hitPlayer(amount) {
  if (world.ended) return;
  world.health = Math.max(0, world.health - amount);
  world.attacked = true;
  if (world.health <= 0) {
    world.ended = true;
    world.started = false;
    setOverlay('Run Failed', 'The plague overwhelmed you. Reboot and try another run.', 'Restart Run', 'accent');
    return;
  }
  updateHUD();
}

function attackEnemies() {
  const playerPos = world.player.position;
  let cleared = 0;
  for (let i = world.enemies.length - 1; i >= 0; i--) {
    const enemy = world.enemies[i];
    const dist = enemy.position.distanceTo(playerPos);
    if (dist < 1.55) {
      enemy.userData.health -= 1.2;
      if (enemy.userData.health <= 0) {
        scene.remove(enemy);
        world.enemies.splice(i, 1);
        world.score += 12 * world.combo;
        world.combo = Math.min(8, world.combo + 0.25);
        cleared += 1;
      }
    }
  }

  if (cleared > 0) {
    world.score += cleared * 12;
    if (world.enemies.length === 0) {
      nextLevel();
    }
  }
}

