601:       function updateEnemies(dt) {
602:         const playerPos = world.player.position;
603:         for (const enemy of world.enemies) {
604:           const data = enemy.userData;
605:           const dx = playerPos.x - enemy.position.x;
606:           const dz = playerPos.z - enemy.position.z;
607:           const distance = Math.hypot(dx, dz);
608:           if (distance > 0) {
609:             enemy.position.x += (dx / distance) * data.speed * dt;
610:             enemy.position.z += (dz / distance) * data.speed * dt;
611:             enemy.rotation.y = Math.atan2(dx, dz);
612:           }
613:           enemy.position.y = 1.2 + Math.sin(world.time * 3 + data.pulse) * 0.18;
614:           const dist = enemy.position.distanceTo(playerPos);
615:           if (dist < 1.6 && world.damageCooldown <= 0) {
616:             hitPlayer(9 + world.level * 1.5);
617:             world.damageCooldown = 0.8;
618:           }
619:         }
